if (!/<!DOCTYPE\s+html>/i.test(code)) {
  throw new Error("The page must start with <!DOCTYPE html> (all on one line).");
}

if (!/<html[^>]*\slang\s*=\s*["'][a-zA-Z-]+["'][^>]*>/i.test(code)) {
  throw new Error("<html> needs a lang attribute, e.g. <html lang=\"en\">.");
}

if (!/<head[\s\S]*<\/head>/i.test(code)) {
  throw new Error("No <head> section found.");
}
if (!/<meta[^>]*charset/i.test(code)) {
  throw new Error("The <head> needs <meta charset=\"UTF-8\">.");
}
const titleMatch = code.match(/<title>([\s\S]*?)<\/title>/i);
if (!titleMatch || !titleMatch[1].trim()) {
  throw new Error("Add a non-empty <title>...</title> in the head.");
}

const h1s = code.match(/<h1[\s>]/gi) || [];
if (h1s.length === 0) {
  throw new Error("Add an <h1> heading with your topic.");
}
if (h1s.length > 1) {
  throw new Error("Use exactly one <h1> per page — it is the main topic.");
}

const paragraphs = (code.match(/<p[\s>][\s\S]*?<\/p>/gi) || [])
  .filter((p) => p.replace(/<\/?p[^>]*>/gi, "").trim().length > 0);
if (paragraphs.length < 2) {
  throw new Error("Write at least two non-empty <p> paragraphs.");
}
